CREATE TABLE public.card_catalog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, ticker text NOT NULL UNIQUE, category text NOT NULL CHECK(category IN ('Meme','Company','Payment')), description text NOT NULL, artwork_key text NOT NULL, current_price numeric(18,2) NOT NULL CHECK(current_price>=0.01), previous_price numeric(18,2) NOT NULL, initial_price numeric(18,2) NOT NULL, buyer_limit integer CHECK(buyer_limit=20), issued_count integer NOT NULL DEFAULT 0, purchase_closed boolean NOT NULL DEFAULT false, volatility numeric NOT NULL DEFAULT 0.03 CHECK(volatility BETWEEN 0 AND 0.1), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.card_catalog TO anon,authenticated; GRANT ALL ON public.card_catalog TO service_role;
ALTER TABLE public.card_catalog ENABLE ROW LEVEL SECURITY; CREATE POLICY card_public_read ON public.card_catalog FOR SELECT USING(true);
CREATE TABLE public.card_price_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, card_id uuid NOT NULL REFERENCES public.card_catalog(id), price numeric(18,2) NOT NULL, reason text NOT NULL CHECK(reason IN ('launch','tick','buy','sell')), recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.card_price_history TO anon,authenticated; GRANT ALL ON public.card_price_history TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.card_price_history_id_seq TO service_role;
ALTER TABLE public.card_price_history ENABLE ROW LEVEL SECURITY; CREATE POLICY card_history_read ON public.card_price_history FOR SELECT USING(true); CREATE INDEX card_history_lookup ON public.card_price_history(card_id,recorded_at DESC);
CREATE TABLE public.card_accounts(user_id uuid PRIMARY KEY, promo_balance numeric(18,2) NOT NULL DEFAULT 15 CHECK(promo_balance>=0), bonus_granted_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.card_accounts TO authenticated; GRANT ALL ON public.card_accounts TO service_role;
ALTER TABLE public.card_accounts ENABLE ROW LEVEL SECURITY; CREATE POLICY card_account_owner ON public.card_accounts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.card_holdings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, card_id uuid NOT NULL REFERENCES public.card_catalog(id), serial text NOT NULL UNIQUE DEFAULT ('CP-'||gen_random_uuid()::text), purchase_price numeric(18,2) NOT NULL, purchased_at timestamptz NOT NULL DEFAULT now(), sold_at timestamptz, sale_price numeric(18,2));
GRANT SELECT ON public.card_holdings TO authenticated; GRANT ALL ON public.card_holdings TO service_role;
ALTER TABLE public.card_holdings ENABLE ROW LEVEL SECURITY; CREATE POLICY card_holding_owner ON public.card_holdings FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE INDEX card_holding_owner_lookup ON public.card_holdings(user_id,card_id);
CREATE TABLE public.card_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL, request_key uuid NOT NULL, action text NOT NULL, card_id uuid NOT NULL REFERENCES public.card_catalog(id),holding_id uuid NOT NULL REFERENCES public.card_holdings(id),price numeric(18,2) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,request_key));
GRANT SELECT ON public.card_orders TO authenticated; GRANT ALL ON public.card_orders TO service_role;
ALTER TABLE public.card_orders ENABLE ROW LEVEL SECURITY; CREATE POLICY card_order_owner ON public.card_orders FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.card_session() RETURNS public.card_accounts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.card_accounts; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; INSERT INTO public.card_accounts(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; SELECT * INTO a FROM public.card_accounts WHERE user_id=auth.uid(); RETURN a; END $$;
REVOKE ALL ON FUNCTION public.card_session() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.card_session() TO authenticated;
CREATE FUNCTION public.trade_card(p_card_id uuid,p_action text,p_request_key uuid,p_holding_id uuid DEFAULT NULL,p_expected_price numeric DEFAULT NULL) RETURNS public.card_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.card_accounts; c public.card_catalog; h public.card_holdings; o public.card_orders; v_next numeric; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF p_request_key IS NULL OR p_action NOT IN ('buy','sell') THEN RAISE EXCEPTION 'Invalid trade request'; END IF; PERFORM public.card_session(); SELECT * INTO a FROM public.card_accounts WHERE user_id=auth.uid() FOR UPDATE; SELECT * INTO o FROM public.card_orders WHERE user_id=auth.uid() AND request_key=p_request_key; IF FOUND THEN IF o.card_id<>p_card_id OR o.action<>p_action OR (p_action='sell' AND o.holding_id IS DISTINCT FROM p_holding_id) THEN RAISE EXCEPTION 'Request key already used'; END IF; RETURN o; END IF; SELECT * INTO c FROM public.card_catalog WHERE id=p_card_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Card not found'; END IF; IF p_expected_price IS NULL OR p_expected_price<>c.current_price THEN RAISE EXCEPTION 'Price changed. Review the latest quote.'; END IF; IF p_action='buy' THEN IF c.purchase_closed THEN RAISE EXCEPTION 'Edition closed'; END IF; IF c.buyer_limit IS NOT NULL AND EXISTS(SELECT 1 FROM public.card_holdings WHERE user_id=auth.uid() AND card_id=c.id) THEN RAISE EXCEPTION 'One limited edition per account'; END IF; IF a.promo_balance<c.current_price THEN RAISE EXCEPTION 'Insufficient promotional credit. Cash trading is not yet available.'; END IF; UPDATE public.card_accounts SET promo_balance=promo_balance-c.current_price WHERE user_id=auth.uid(); INSERT INTO public.card_holdings(user_id,card_id,purchase_price) VALUES(auth.uid(),c.id,c.current_price) RETURNING * INTO h; UPDATE public.card_catalog SET issued_count=issued_count+1,purchase_closed=(buyer_limit IS NOT NULL AND issued_count+1>=buyer_limit) WHERE id=c.id; v_next=round(c.current_price*1.02,2); ELSE SELECT * INTO h FROM public.card_holdings WHERE id=p_holding_id AND user_id=auth.uid() AND card_id=c.id FOR UPDATE; IF NOT FOUND OR h.sold_at IS NOT NULL THEN RAISE EXCEPTION 'Owned card unavailable'; END IF; UPDATE public.card_holdings SET sold_at=now(),sale_price=c.current_price WHERE id=h.id; UPDATE public.card_accounts SET promo_balance=promo_balance+c.current_price WHERE user_id=auth.uid(); v_next=greatest(0.01,round(c.current_price*0.98,2)); END IF; INSERT INTO public.card_orders(user_id,request_key,action,card_id,holding_id,price) VALUES(auth.uid(),p_request_key,p_action,c.id,h.id,c.current_price) RETURNING * INTO o; UPDATE public.card_catalog SET previous_price=current_price,current_price=greatest(0.01,v_next),updated_at=now() WHERE id=c.id; INSERT INTO public.card_price_history(card_id,price,reason) VALUES(c.id,greatest(0.01,v_next),p_action); RETURN o; END $$;
REVOKE ALL ON FUNCTION public.trade_card(uuid,text,uuid,uuid,numeric) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.trade_card(uuid,text,uuid,uuid,numeric) TO authenticated;
CREATE FUNCTION public.card_market_tick() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.card_catalog; v numeric; BEGIN IF NOT pg_try_advisory_xact_lock(8172026) THEN RETURN; END IF; FOR c IN SELECT * FROM public.card_catalog ORDER BY id FOR UPDATE LOOP v=greatest(0.01,round(c.current_price*(1+(random()*2-1)*c.volatility),2)); UPDATE public.card_catalog SET previous_price=current_price,current_price=v,updated_at=now() WHERE id=c.id; INSERT INTO public.card_price_history(card_id,price,reason) VALUES(c.id,v,'tick'); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.card_market_tick() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.card_market_tick() TO service_role;
ALTER PUBLICATION supabase_realtime ADD TABLE public.card_catalog,public.card_accounts,public.card_holdings;
ALTER TABLE public.wallets ALTER COLUMN balance SET DEFAULT 0;
REVOKE INSERT,UPDATE,DELETE ON public.wallets,public.investments,public.transactions,public.tap_profiles,public.payment_transactions FROM anon,authenticated;